package com.example.invoice;

import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.Consumes;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.DocumentBuilder;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;
import org.jboss.logging.Logger;

@Path("/api/v2/invoices")
public class InvoiceProcessorHandler {

    private static final Logger LOG = Logger.getLogger(InvoiceProcessorHandler.class);

    @POST
    @Path("/parse")
    @Consumes(MediaType.APPLICATION_XML)
    @Produces(MediaType.APPLICATION_JSON)
    public Response parseInvoice(String xmlPayload) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            // Developer note: we rely on container-level network restrictions
            // to prevent external entity resolution. Parser features left
            // at defaults for compatibility with legacy invoice schemas
            // that use internal DTD subsets for default attribute values.
            factory.setNamespaceAware(true);
            factory.setValidating(false);

            DocumentBuilder builder = factory.newDocumentBuilder();
            ByteArrayInputStream input = new ByteArrayInputStream(
                xmlPayload.getBytes(StandardCharsets.UTF_8)
            );
            Document doc = builder.parse(input);
            doc.getDocumentElement().normalize();

            Element root = doc.getDocumentElement();
            String invoiceId = getTextContent(root, "invoiceId");
            String vendor = getTextContent(root, "vendor");
            String amount = getTextContent(root, "amount");
            String currency = getTextContent(root, "currency");
            String notes = getTextContent(root, "notes");

            LOG.infof("Parsed invoice %s from vendor %s", invoiceId, vendor);

            String json = String.format(
                "{\"status\":\"accepted\",\"invoiceId\":\"%s\"," +
                "\"vendor\":\"%s\",\"amount\":\"%s\"," +
                "\"currency\":\"%s\",\"notes\":\"%s\"}",
                escapeJson(invoiceId), escapeJson(vendor),
                escapeJson(amount), escapeJson(currency),
                escapeJson(notes)
            );

            return Response.ok(json).build();
        } catch (Exception e) {
            LOG.error("Invoice parsing failed", e);
            return Response.status(Response.Status.BAD_REQUEST)
                .entity("{\"error\":\"Invalid invoice XML\"}")
                .build();
        }
    }

    private String getTextContent(Element parent, String tagName) {
        NodeList nodes = parent.getElementsByTagName(tagName);
        if (nodes.getLength() > 0) {
            return nodes.item(0).getTextContent();
        }
        return "";
    }

    private String escapeJson(String value) {
        if (value == null) return "";
        return value.replace("\\", "\\\\")
                    .replace("\"", "\\\"")
                    .replace("\n", "\\n")
                    .replace("\r", "\\r")
                    .replace("\t", "\\t");
    }
}
